    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
  getEntityState(state: WorldStateHandle, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldStateHandle): Record<string, string>;
}

const createInitialState = (): WorldStateHandle => ({
  entities: {
    Vok: "pex",
  },
});

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return createInitialState();
  },

  applyOperation(state, operationDisplayName) {
    if (operationDisplayName === "advanceVok") {
      if (state.entities.Vok !== "pex") {
        return {
          success: false,
          error: "Vok can only be advanced from pex",
        };
      }

      return {
        success: true,
        newState: {
          entities: {
            ...state.entities,
            Vok: "dor",
          },
        },
      };
    }

    if (operationDisplayName === "recoverVok") {
      if (state.entities.Vok !== "dor") {
        return {
          success: false,
          error: "Vok can only be recovered from dor",
        };
      }

      return {
        success: true,
        newState: {
          entities: {
            ...state.entities,
            Vok: "pex",
          },
        },
      };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state, entityDisplayName) {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    return { ...state.entities };
  },
};
